exercises.solution:
using System;

public static class Initials
{
    public static string Of(string fullName)
    {
        string result = "";
        foreach (string p in fullName.Split(' ', StringSplitOptions.RemoveEmptyEntries))
            result += char.ToUpper(p[0]) + ".";
        return result;
    }
}
